/**
 * @method
 * @name ipt_a010From_onkeyup
 * @description ipt_a010From 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_a010From_onkeyup = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        setNumberTypeWithComma(selfVar);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst15500.ipt_a010From_onkeyup' }); }
};

